  const sup = (a, n) => `${a}<sup>${n}</sup>`;
  const nz = (a, b) => { let x; do { x = R(a, b); } while (x === 0); return x; };
  const topics = [];

  // =====================================================================
  // 1. TẬP HỢP & SỐ TỰ NHIÊN
