  topics.push({
    id: 'g6_power', icon: '⚡', title: 'Lũy thừa & Thứ tự thực hiện phép tính',
    tagline: 'aⁿ = a·a·…·a · Nhân, chia hai lũy thừa cùng cơ số',
    summary: 'Lũy thừa bậc n của a là tích của n thừa số bằng a. Thứ tự: Lũy thừa → Nhân, chia → Cộng, trừ; có ngoặc thì ( ) → [ ] → { }.',
    prereqs: ['g6_sets'],
    rules: [
      { title: 'Định nghĩa lũy thừa', desc: 'aⁿ = a · a · … · a (n thừa số a). a là cơ số, n là số mũ.', formula: 'a¹ = a; a⁰ = 1 (a ≠ 0)', example: '2⁵ = 2·2·2·2·2 = 32', tip: 'a² đọc là “a bình phương”, a³ là “a lập phương”.' },
      { title: 'Nhân, chia hai lũy thừa cùng cơ số', desc: 'Nhân: giữ nguyên cơ số, CỘNG số mũ. Chia: giữ nguyên cơ số, TRỪ số mũ.', formula: 'aᵐ · aⁿ = aᵐ⁺ⁿ;  aᵐ : aⁿ = aᵐ⁻ⁿ (m ≥ n)', example: '3⁴ · 3² = 3⁶; 5⁷ : 5³ = 5⁴', tip: 'Không nhân số mũ khi nhân hai lũy thừa!' },
      { title: 'Thứ tự thực hiện phép tính', desc: 'Không ngoặc: Lũy thừa → Nhân chia (trái sang phải) → Cộng trừ (trái sang phải). Có ngoặc: ( ) → [ ] → { }.', example: '2 · 3² − 10 : 5 = 2 · 9 − 2 = 18 − 2 = 16', tip: 'Thần chú: “Lũy – Nhân Chia – Cộng Trừ”.' }
    ],
    poem: ['Lũy thừa đứng trước tiên,', 'Nhân chia kế tiếp, cộng liền trừ sau!', 'Ngoặc tròn, vuông, nhọn theo nhau,', 'Trong ra ngoài đó, chẳng đâu sai đường!'],
    pitfalls: [
      { wrong: '2³ = 6 (lấy 2 × 3)', right: '2³ = 2 · 2 · 2 = 8', why: 'Lũy thừa là nhân cơ số với chính nó, không phải nhân với số mũ.' },
      { wrong: '3² · 3⁴ = 9⁶ hoặc 3⁸', right: '3² · 3⁴ = 3⁶', why: 'Giữ nguyên cơ số và cộng số mũ.' },
      { wrong: '20 − 4 · 3 = 16 · 3 = 48', right: '20 − 4 · 3 = 20 − 12 = 8', why: 'Nhân trước, trừ sau.' }
    ],
    examples: [{ q: 'Tính: 5 · 2³ − 36 : 3²', steps: ['Lũy thừa: 2³ = 8; 3² = 9.', 'Nhân chia: 5 · 8 = 40; 36 : 9 = 4.', 'Trừ: 40 − 4 = <b>36</b>.'] }],
    gens: [
      { level: 1, name: 'Tính lũy thừa', fn() { const a = R(2, 5), n = a === 2 ? R(3, 7) : R(2, 4); const v = Math.pow(a, n); return Q({ text: `Giá trị của ${sup(a, n)} là:`, answer: v, wrongs: [a * n, Math.pow(a, n - 1), Math.pow(n, a) === v ? v + a : Math.pow(n, a)], hint: `Nhân ${n} thừa số ${a} với nhau.`, steps: [`${sup(a, n)} = ${Array(n).fill(a).join(' · ')} = <b>${v}</b>.`] }); } },
      { level: 1, name: 'Viết gọn lũy thừa', fn() { const a = R(2, 9), m = R(2, 6), n = R(2, 6); const mul = R(0, 1); if (!mul && m <= n + 1) return this.fn(); const e = mul ? m + n : m - n; return Q({ text: `Viết kết quả dưới dạng một lũy thừa: <b>${sup(a, m)} ${mul ? '·' : ':'} ${sup(a, n)}</b>`, answer: sup(a, e), options: [sup(a, e), sup(a, mul ? m * n : m + n), sup(a * a, e), sup(a, mul ? Math.abs(m - n) || 1 : m * n)], hint: mul ? 'Nhân cùng cơ số: cộng số mũ.' : 'Chia cùng cơ số: trừ số mũ.', steps: [`${sup(a, m)} ${mul ? '·' : ':'} ${sup(a, n)} = ${sup(a, `${m} ${mul ? '+' : '−'} ${n}`)} = <b>${sup(a, e)}</b>.`] }); } },
      { level: 1, name: 'Thứ tự phép tính cơ bản', fn() { const a = R(10, 50), b = R(2, 9), c = R(2, 9); const v = a + b * c; return Q({ text: `Tính: <b>${a} + ${b} · ${c}</b>`, answer: v, wrongs: [(a + b) * c, v + 1, a * b + c], hint: 'Nhân trước, cộng sau.', steps: [`${b} · ${c} = ${b * c}.`, `${a} + ${b * c} = <b>${v}</b>.`] }); } },
      { level: 2, name: 'Biểu thức có lũy thừa', fn() { const a = R(2, 6), b = R(2, 3), c = R(2, 5), d = R(2, 4); const p = Math.pow(b, 3), q = Math.pow(c, 2); const k = R(1, 5); const v = a * p - k * q; if (v < 0) return this.fn(); return Q({ text: `Tính: <b>${a} · ${sup(b, 3)} − ${k * q * d} : ${d}</b>`, answer: v, hint: 'Lũy thừa → nhân chia → cộng trừ.', steps: [`${sup(b, 3)} = ${p}.`, `${a} · ${p} = ${a * p}; ${k * q * d} : ${d} = ${k * q}.`, `${a * p} − ${k * q} = <b>${v}</b>.`] }); } },
      { level: 2, name: 'Biểu thức có ngoặc', fn() { const a = R(2, 9), b = R(10, 30), c = R(2, 9), d = R(2, 5); const inner = b - c * 2; if (inner <= 0) return this.fn(); const v = a * inner + d * d; return Q({ text: `Tính: <b>${a} · (${b} − ${c} · 2) + ${sup(d, 2)}</b>`, answer: v, wrongs: [a * (b - c) * 2 + d * d, v + a, a * inner + d * 2], hint: 'Tính trong ngoặc trước (nhân trước trừ sau), rồi đến lũy thừa.', steps: [`Trong ngoặc: ${c} · 2 = ${c * 2}; ${b} − ${c * 2} = ${inner}.`, `${sup(d, 2)} = ${d * d}.`, `${a} · ${inner} + ${d * d} = ${a * inner} + ${d * d} = <b>${v}</b>.`] }); } },
      { level: 2, name: 'Tìm x lũy thừa', fn() { const v = R(0, 3), a = pick([2, 3, 4, 5, 10]); const n = a === 2 ? R(2, 8) : a === 10 ? R(2, 6) : R(2, 4); const N = Math.pow(a, n); if (v === 1) { const b = R(2, 9), e = pick([2, 3]); return Q({ text: `Tìm số tự nhiên x, biết: <b>${sup('x', e)} = ${fmt(Math.pow(b, e))}</b>`, answer: b, hint: `Số nào ${e === 2 ? 'bình phương' : 'lập phương'} lên bằng ${fmt(Math.pow(b, e))}?`, steps: [`${fmt(Math.pow(b, e))} = ${sup(b, e)}.`, `${sup('x', e)} = ${sup(b, e)} ⇒ x = <b>${b}</b>.`] }); } if (v === 2) return Q({ text: `Tìm số tự nhiên x, biết: <b>${sup(a, 'x + 1')} = ${fmt(N)}</b>`, answer: n - 1, hint: `Viết ${fmt(N)} dưới dạng lũy thừa cơ số ${a}.`, steps: [`${fmt(N)} = ${sup(a, n)}.`, `x + 1 = ${n} ⇒ x = <b>${n - 1}</b>.`] }); if (v === 3) { const k = pick([2, 3, 5]); return Q({ text: `Tìm số tự nhiên x, biết: <b>${k} · ${sup(a, 'x')} = ${fmt(k * N)}</b>`, answer: n, hint: `Tìm ${sup(a, 'x')} trước: chia ${fmt(k * N)} cho ${k}.`, steps: [`${sup(a, 'x')} = ${fmt(k * N)} : ${k} = ${fmt(N)} = ${sup(a, n)}.`, `Vậy x = <b>${n}</b>.`] }); } return Q({ text: `Tìm số tự nhiên x, biết: <b>${sup(a, 'x')} = ${fmt(N)}</b>`, answer: n, hint: `Viết ${fmt(N)} dưới dạng lũy thừa cơ số ${a}.`, steps: [`${fmt(N)} = ${sup(a, n)}.`, `${sup(a, 'x')} = ${sup(a, n)} ⇒ x = <b>${n}</b>.`] }); } },
      { level: 3, name: 'Ngoặc nhiều tầng', fn() { const a = R(2, 5), b = R(10, 20), c = R(2, 6); const s = b - c; const t = s * a; const k = R(1, 3); const v = 100 + k * 50 - t; if (v < 0) return this.fn(); return Q({ text: `Tính: <b>${100 + k * 50} − [${a} · (${b} − ${c})]</b>`, answer: v, hint: 'Ngoặc tròn → ngoặc vuông → bên ngoài.', steps: [`( ): ${b} − ${c} = ${s}.`, `[ ]: ${a} · ${s} = ${t}.`, `${100 + k * 50} − ${t} = <b>${v}</b>.`] }); } },
      { level: 3, name: 'Tìm x hai bước', fn() { const a = pick([2, 3]), n = R(2, 5), b = R(1, 20); const x = Math.pow(a, n) + b; const k = R(2, 5); return Q({ text: `Tìm x, biết: <b>${k} · (x − ${b}) = ${k} · ${sup(a, n)}</b>`, answer: x, hint: `Chia cả hai vế cho ${k}, rồi tính ${sup(a, n)}.`, steps: [`x − ${b} = ${sup(a, n)} = ${Math.pow(a, n)}.`, `x = ${Math.pow(a, n)} + ${b} = <b>${x}</b>.`] }); } },
      { level: 3, name: 'So sánh lũy thừa', fn() { let A, B, steps, c; if (R(0, 1)) { const [a, m, b, n] = pick([[2, 3, 3, 2], [3, 2, 2, 3], [5, 2, 3, 3], [2, 5, 5, 2], [2, 4, 3, 3], [3, 3, 5, 2], [2, 7, 5, 3], [7, 2, 2, 5]]); const x = pick([10, 20, 50, 100, 200]); A = sup(a, m * x); B = sup(b, n * x); const va = Math.pow(a, m), vb = Math.pow(b, n); c = va < vb ? '<' : '>'; steps = [`${A} = (${sup(a, m)})<sup>${x}</sup> = ${sup(va, x)}.`, `${B} = (${sup(b, n)})<sup>${x}</sup> = ${sup(vb, x)}.`, `Cùng số mũ ${x}, vì ${va} ${c} ${vb} nên ${A} ${c} ${B}.`]; } else { const base = pick([2, 3]), p = R(2, 4); let q; do { q = R(2, 4); } while (q === p); const e1 = R(3, 12), e2 = R(3, 12); A = sup(Math.pow(base, p), e1); B = sup(Math.pow(base, q), e2); const s1 = p * e1, s2 = q * e2; c = s1 < s2 ? '<' : s1 > s2 ? '>' : '='; steps = [`${A} = ${sup(base, s1)}; ${B} = ${sup(base, s2)}.`, `Cùng cơ số ${base}: số mũ ${s1} ${c} ${s2} nên ${A} ${c} ${B}.`]; } return Q({ text: `So sánh ${A} và ${B}`, answer: `${A} ${c} ${B}`, options: ['<', '>', '='].map(o => `${A} ${o} ${B}`), shuffle: false, hint: 'Đưa về cùng cơ số hoặc cùng số mũ.', steps }); } }
    ]
  });

