    poem: ['Cùng dấu cộng lại, giữ dấu chung,', 'Khác dấu trừ đi, dấu số lớn dùng!', 'Nhân chia cùng dấu thì dương,', 'Khác dấu thì âm, nhớ thường chẳng quên!'],
    pitfalls: [
      { wrong: '−7 > −3 (vì 7 > 3)', right: '−7 < −3', why: 'Trên trục số, −7 nằm bên trái −3.' },
      { wrong: '(−3)² = −9', right: '(−3)² = (−3)·(−3) = 9', why: 'Hai thừa số âm nhân với nhau cho kết quả dương.' },
      { wrong: '10 − (4 − 6) = 10 − 4 − 6 = 0', right: '10 − 4 + 6 = 12', why: 'Bỏ ngoặc có dấu − phải đổi dấu MỌI số hạng.' }
    ],
    examples: [{ q: 'Nhiệt độ buổi sáng ở Sa Pa là −3°C, buổi trưa tăng thêm 8°C. Hỏi nhiệt độ buổi trưa?', steps: ['(−3) + 8 = <b>5</b> (°C).'], visual: { type: 'numberline', min: -5, max: 6, jumps: [{ from: -3, to: 5, label: '+8' }] } }],
    gens: [
      { level: 1, name: 'So sánh số nguyên', fn() { const a = nz(-20, 20), b = nz(-20, 20); if (a === b) return this.fn(); const s = a > b ? '>' : '<'; return Q({ text: `Chọn dấu thích hợp: <b>${fmt(a)} ... ${fmt(b)}</b>`, answer: s, options: ['>', '<', '='], shuffle: false, hint: 'Số nào nằm bên phải trên trục số thì lớn hơn.', steps: [`Trên trục số, ${fmt(Math.max(a, b))} nằm bên phải ${fmt(Math.min(a, b))}.`, `Vậy ${fmt(a)} <b>${s}</b> ${fmt(b)}.`], solVisual: { type: 'numberline', min: Math.min(a, b, 0) - 1, max: Math.max(a, b, 0) + 1, step: Math.max(a, b) - Math.min(a, b) > 20 ? 2 : 1, points: [{ v: a, label: fmt(a) }, { v: b, label: fmt(b), color: '#4a7bd8' }] } }); } },
      { level: 1, name: 'Cộng số nguyên', fn() { const a = nz(-30, 30), b = nz(-30, 30); return Q({ text: `Tính: <b>${fmt(a)} + ${N(b)}</b>`, answer: a + b, wrongs: [-(a + b), a - b, Math.abs(a) + Math.abs(b)].filter(x => x !== a + b), mcOpts: { positive: false }, hint: (a < 0) === (b < 0) ? 'Cùng dấu: cộng phần số, giữ dấu chung.' : 'Khác dấu: lấy phần số lớn trừ phần số nhỏ, dấu theo số có phần số lớn hơn.', steps: [(a < 0) === (b < 0) ? `Cùng dấu: ${Math.abs(a)} + ${Math.abs(b)} = ${Math.abs(a + b)}, giữ dấu ${a < 0 ? '“−”' : '“+”'}.` : `Khác dấu: ${Math.max(Math.abs(a), Math.abs(b))} − ${Math.min(Math.abs(a), Math.abs(b))} = ${Math.abs(a + b)}, lấy dấu của ${Math.abs(a) > Math.abs(b) ? fmt(a) : fmt(b)}.`, `Kết quả: <b>${fmt(a + b)}</b>.`], solVisual: Math.abs(a) <= 15 && Math.abs(b) <= 15 ? { type: 'numberline', min: Math.min(0, a, a + b) - 1, max: Math.max(0, a, a + b) + 1, step: 1, jumps: [{ from: 0, to: a, label: fmt(a) }, { from: a, to: a + b, label: (b > 0 ? '+' : '') + fmt(b) }] } : null }); } },
      { level: 1, name: 'Trừ số nguyên', fn() { const a = R(-20, 20), b = nz(-20, 20); return Q({ text: `Tính: <b>${fmt(a)} − ${N(b)}</b>`, answer: a - b, hint: 'a − b = a + (−b): đổi phép trừ thành cộng với số đối.', steps: [`${fmt(a)} − ${N(b)} = ${fmt(a)} + ${N(-b)}.`, `= <b>${fmt(a - b)}</b>.`] }); } },
      { level: 2, name: 'Nhân chia số nguyên', fn() { const a = nz(-12, 12), b = pick([1, -1]) * R(2, 9); const mul = R(0, 1); if (mul) return Q({ text: `Tính: <b>${N(a)} · ${N(b)}</b>`, answer: a * b, wrongs: [-a * b, a + b, a * b + (a * b > 0 ? 1 : -1)], mcOpts: { positive: false }, hint: 'Cùng dấu → dương; khác dấu → âm.', steps: [`Phần số: ${Math.abs(a)} · ${Math.abs(b)} = ${Math.abs(a * b)}.`, `${(a < 0) === (b < 0) ? 'Cùng dấu → dương' : 'Khác dấu → âm'}: <b>${fmt(a * b)}</b>.`] }); return Q({ text: `Tính: <b>${N(a * b)} : ${N(b)}</b>`, answer: a, wrongs: [-a, a * b - b, b], mcOpts: { positive: false }, hint: 'Chia cũng theo quy tắc dấu như nhân.', steps: [`${Math.abs(a * b)} : ${Math.abs(b)} = ${Math.abs(a)}; ${(a * b < 0) === (b < 0) ? 'cùng dấu → dương' : 'khác dấu → âm'}.`, `Kết quả: <b>${fmt(a)}</b>.`] }); } },
      { level: 2, name: 'Bài toán thực tế', fn() { const T = pick([
        () => { const t = R(-8, 3), d = R(3, 12); return { t: `Nhiệt độ lúc 6 giờ sáng ở Mẫu Sơn là ${fmt(t)}°C. Đến trưa nhiệt độ tăng thêm ${d}°C. Nhiệt độ lúc trưa là bao nhiêu độ C?`, a: t + d, s: [`${fmt(t)} + ${d} = <b>${fmt(t + d)}</b> (°C).`], v: { type: 'numberline', min: Math.min(t, 0) - 1, max: t + d + 1, jumps: [{ from: t, to: t + d, label: '+' + d }] } }; },
        () => { const h = R(5, 30) * 10, d = R(2, 10) * 10; return { t: `Một tàu ngầm đang ở độ sâu ${h} m dưới mực nước biển (tức −${h} m). Tàu lặn sâu thêm ${d} m. Vị trí mới của tàu là bao nhiêu mét so với mực nước biển?`, a: -h - d, s: [`(−${h}) + (−${d}) = <b>${fmt(-h - d)}</b> (m).`] }; },
        () => { const m = R(2, 9) * 10000, s = R(1, 5) * 10000, k = R(3, 6) * 10000; return { t: `Ông An có ${fmt(m)} đồng, ông mua hàng hết ${fmt(m + k)} đồng (phải nợ phần còn thiếu). Số tiền của ông An (tính theo số nguyên) lúc này là bao nhiêu đồng?`, a: -k, s: [`${fmt(m)} − ${fmt(m + k)} = <b>${fmt(-k)}</b> (đồng), nghĩa là ông nợ ${fmt(k)} đồng.`], dummy: s }; },
        () => { const y = R(100, 600); return { t: `Nhà toán học Pythagoras sinh năm ${y} trước Công nguyên (năm −${y}). Năm 2026 là bao nhiêu năm sau năm ông sinh?`, a: 2026 + y, s: [`2026 − (−${y}) = 2026 + ${y} = <b>${2026 + y}</b> (năm).`] }; }
      ])(); return Q({ text: T.t, answer: T.a, hint: 'Biểu diễn bằng số nguyên âm rồi tính.', steps: T.s, solVisual: T.v }); } },
      { level: 2, name: 'Quy tắc dấu ngoặc', fn() { const a = R(10, 50), b = R(5, 30), c = R(5, 40); const v = a - (b - c); return Q({ text: `Tính: <b>${a} − (${b} − ${c})</b>`, answer: v, wrongs: [a - b - c, a + b - c, -v], mcOpts: { positive: false }, hint: 'Bỏ ngoặc có dấu “−” đằng trước: đổi dấu mọi số hạng trong ngoặc.', steps: [`${a} − (${b} − ${c}) = ${a} − ${b} + ${c}`, `= <b>${fmt(v)}</b>.`] }); } },
      { level: 3, name: 'Tính nhanh', fn() { const a = R(100, 999), b = R(10, 99), c = R(10, 99); const v = (a + b) - (a - c); return Q({ text: `Tính nhanh: <b>(${a} + ${b}) − (${a} − ${c})</b>`, answer: v, hint: `Bỏ ngoặc rồi nhóm ${a} − ${a}.`, steps: [`= ${a} + ${b} − ${a} + ${c}`, `= (${a} − ${a}) + ${b} + ${c} = 0 + ${b + c} = <b>${v}</b>.`] }); } },
      { level: 3, name: 'Tìm x số nguyên', fn() { const x = nz(-20, 20), a = nz(-15, 15), k = pick([2, 3, -2, -3, 4]); const r = k * (x + a); return Q({ text: `Tìm số nguyên x, biết: <b>${N(k)} · (x + ${N(a)}) = ${fmt(r)}</b>`, answer: x, hint: `Chia cả hai vế cho ${fmt(k)} trước.`, steps: [`x + ${N(a)} = ${fmt(r)} : ${N(k)} = ${fmt(x + a)}.`, `x = ${fmt(x + a)} − ${N(a)} = <b>${fmt(x)}</b>.`] }); } },
      { level: 3, name: 'Tổng dãy số nguyên', fn() { const n = R(5, 30); const s = 0; void s; return Q({ text: `Tính tổng tất cả các số nguyên x thỏa mãn <b>−${n} ≤ x ≤ ${n}</b>.`, answer: 0, wrongs: [n, 2 * n, -n], mcOpts: { positive: false }, hint: 'Ghép từng cặp số đối nhau: (−a) + a = 0.', steps: [`Các số: −${n}, −${n - 1}, …, 0, …, ${n - 1}, ${n}.`, `Ghép cặp (−${n} + ${n}) + (−${n - 1} + ${n - 1}) + … + 0 = <b>0</b>.`] }); } }
    ]
