  const F = (a, b) => fracHtml(a, b);
  topics.push({
    id: 'g6_frac', icon: '🍕', title: 'Phân số',
    tagline: 'Rút gọn · Quy đồng · So sánh · Cộng trừ nhân chia · Giá trị phân số của một số',
    summary: 'Phân số a/b (b ≠ 0) biểu thị a phần bằng nhau trong b phần. Phân số có thể có tử và mẫu là số nguyên.',
    prereqs: ['g6_gcd', 'g6_int'],
    rules: [
      { title: 'Tính chất cơ bản – Rút gọn', desc: 'Nhân hoặc chia cả tử và mẫu cho cùng một số khác 0 thì được phân số bằng nó. Rút gọn: chia tử và mẫu cho ƯCLN của chúng.', example: `${frac(18, 24)} = ${frac('18 : 6', '24 : 6')} = ${frac(3, 4)}`, tip: 'Phân số tối giản: tử và mẫu chỉ có ước chung là 1 và −1.', visual: { type: 'fraction', items: [{ n: 3, d: 4, label: '3/4' }, { n: 6, d: 8, label: '6/8' }] } },
      { title: 'So sánh phân số', desc: 'Cùng mẫu dương: tử lớn hơn thì lớn hơn. Khác mẫu: quy đồng mẫu rồi so sánh tử.', example: `${frac(2, 3)} và ${frac(3, 5)}: ${frac(10, 15)} > ${frac(9, 15)}`, tip: 'Mẫu chung nên chọn là BCNN của các mẫu.', visual: { type: 'fraction', shape: 'bar', items: [{ n: 2, d: 3, label: '2/3' }, { n: 3, d: 5, label: '3/5' }] } },
      { title: 'Cộng, trừ phân số', desc: 'Cùng mẫu: cộng (trừ) tử, giữ mẫu. Khác mẫu: quy đồng rồi cộng (trừ).', formula: 'a/m + b/m = (a + b)/m', example: `${frac(1, 4)} + ${frac(2, 3)} = ${frac(3, 12)} + ${frac(8, 12)} = ${frac(11, 12)}`, tip: 'Rút gọn kết quả nếu được.' },
      { title: 'Nhân, chia phân số', desc: 'Nhân: tử nhân tử, mẫu nhân mẫu. Chia: nhân với phân số nghịch đảo của số chia.', formula: 'a/b · c/d = (a·c)/(b·d);  a/b : c/d = a/b · d/c', example: `${frac(2, 3)} : ${frac(4, 5)} = ${frac(2, 3)} · ${frac(5, 4)} = ${frac(10, 12)} = ${frac(5, 6)}`, tip: 'Nên rút gọn chéo trước khi nhân cho nhẹ số.' },
      { title: 'Hai bài toán cơ bản về phân số', desc: '1) Tìm giá trị phân số của một số: m/n của b là b · m/n. 2) Tìm một số biết giá trị phân số của nó: m/n của số đó bằng a → số đó = a : m/n.', example: `${frac(3, 4)} của 40 là 40 · ${frac(3, 4)} = 30. ${frac(2, 5)} của một số là 12 → số đó = 12 : ${frac(2, 5)} = 30.`, tip: '“của” → nhân; “biết … của nó bằng” → chia.', visual: { type: 'bar', rows: [{ label: '40 HS', segs: [{ v: 10, inner: '10' }, { v: 10, inner: '10' }, { v: 10, inner: '10' }, { v: 10, inner: '10', dashed: true }] }] } }
    ],
    poem: ['Cùng mẫu cộng tử giữ nguyên,', 'Khác mẫu quy đồng rồi liền cộng ngay!', 'Chia thì đảo ngược phân này,', 'Rồi nhân tử mẫu, thế này là xong!'],
    pitfalls: [
      { wrong: `${frac(1, 2)} + ${frac(1, 3)} = ${frac(2, 5)}`, right: `${frac(3, 6)} + ${frac(2, 6)} = ${frac(5, 6)}`, why: 'Không cộng mẫu với mẫu!' },
      { wrong: `${frac(2, 3)} : ${frac(4, 5)} = ${frac(8, 15)}`, right: `${frac(2, 3)} · ${frac(5, 4)} = ${frac(5, 6)}`, why: 'Chia phải đảo ngược phân số thứ hai rồi nhân.' }
    ],
    examples: [{ q: 'Lớp 6A có 40 học sinh, trong đó 3/8 số học sinh thích bóng đá. Hỏi có bao nhiêu bạn thích bóng đá?', steps: [`Số học sinh thích bóng đá: 40 · ${frac(3, 8)} = <b>15</b> (học sinh).`], visual: { type: 'bar', rows: [{ label: '40 HS', segs: [1, 2, 3, 4, 5, 6, 7, 8].map(i => ({ v: 5, inner: i <= 3 ? '5' : '', dashed: i > 3 })) }] } }],
    gens: [
      { level: 1, name: 'Rút gọn', fn() { const b0 = R(2, 12), a0 = R(1, b0 - 1); if (gcd(a0, b0) !== 1) return this.fn(); const k = R(2, 9); const a = a0 * k, b = b0 * k; return Q({ text: `Rút gọn phân số ${frac(a, b)} về tối giản.`, answer: `${a0}/${b0}`, simplest: true, inputHint: 'Nhập dạng a/b', answerText: `${a0}/${b0}`, hint: `Chia cả tử và mẫu cho ƯCLN(${a}, ${b}).`, steps: [`ƯCLN(${a}, ${b}) = ${k}.`, `${frac(a, b)} = ${frac(`${a} : ${k}`, `${b} : ${k}`)} = <b>${frac(a0, b0)}</b>.`], solVisual: { type: 'fraction', items: [{ n: a0, d: b0 }] } }); } },
      { level: 1, name: 'Đọc phân số từ hình', fn() { const d = R(2, 10), n = R(1, d - 1); return Q({ text: 'Phần tô màu biểu diễn phân số nào?', visual: { type: 'fraction', items: [{ n, d, label: ' ' }], shape: pick(['circle', 'bar']) }, answer: `${n}/${d}`, options: [`${n}/${d}`, `${d - n}/${d}`, `${n}/${d + 1}`, `${d}/${n}`].filter((x, i, a) => a.indexOf(x) === i), hint: 'Mẫu = tổng số phần bằng nhau; tử = số phần được tô.', steps: [`Hình chia thành ${d} phần bằng nhau, tô ${n} phần → <b>${n}/${d}</b>.`] }); } },
      { level: 1, name: 'So sánh phân số', fn() { const b = R(3, 9), d = R(3, 9); const a = R(1, b - 1), c = R(1, d - 1); if (a * d === b * c || b === d || gcd(a, b) !== 1 || gcd(c, d) !== 1) return this.fn(); const s = a * d > b * c ? '>' : '<'; const L = lcm(b, d); return Q({ text: `So sánh: ${frac(a, b)} ... ${frac(c, d)}`, answer: s, options: ['>', '<', '='], shuffle: false, hint: 'Quy đồng mẫu số rồi so sánh tử số.', steps: [`Mẫu chung: ${L}.`, `${frac(a, b)} = ${frac(a * L / b, L)}; ${frac(c, d)} = ${frac(c * L / d, L)}.`, `${a * L / b} ${s} ${c * L / d} nên ${frac(a, b)} <b>${s}</b> ${frac(c, d)}.`], solVisual: { type: 'fraction', shape: 'bar', items: [{ n: a, d: b }, { n: c, d: d }] } }); } },
      { level: 2, name: 'Cộng trừ phân số', fn() { const b = R(2, 9), d = R(2, 9); const a = nz(-5, 7), c = R(1, 7); if (b === d || gcd(Math.abs(a), b) !== 1 || gcd(c, d) !== 1) return this.fn(); const op = R(0, 1); const num = op ? a * d + c * b : a * d - c * b, den = b * d; const ans = fracStr(num, den); return Q({ text: `Tính: ${a < 0 ? '−' + frac(-a, b) : frac(a, b)} ${op ? '+' : '−'} ${frac(c, d)}`, answer: ans, simplest: true, hint: 'Quy đồng mẫu rồi cộng (trừ) tử số, rút gọn kết quả. Nhập dạng a/b.', steps: [`Mẫu chung: ${lcm(b, d)}.`, `= ${F(a * lcm(b, d) / b, lcm(b, d))} ${op ? '+' : '−'} ${F(c * lcm(b, d) / d, lcm(b, d))}`, `= <b>${F(num, den)}</b>.`] }); } },
      { level: 2, name: 'Nhân chia phân số', fn() { const a = R(1, 9), b = R(2, 9), c = R(1, 9), d = R(2, 9); if (gcd(a, b) !== 1 || gcd(c, d) !== 1) return this.fn(); const mul = R(0, 1); const num = mul ? a * c : a * d, den = mul ? b * d : b * c; const ans = fracStr(num, den); return Q({ text: `Tính: ${frac(a, b)} ${mul ? '·' : ':'} ${frac(c, d)}`, answer: ans, simplest: true, hint: mul ? 'Tử nhân tử, mẫu nhân mẫu rồi rút gọn.' : 'Nhân với phân số nghịch đảo của số chia.', steps: [mul ? `= ${frac(`${a} · ${c}`, `${b} · ${d}`)} = ${frac(num, den)}` : `= ${frac(a, b)} · ${frac(d, c)} = ${frac(num, den)}`, `= <b>${F(num, den)}</b>.`], options: undefined }); } },
      { level: 2, name: 'Phân số của một số', fn() { const d = R(2, 9), n = R(1, d - 1), k = R(2, 12); const b = d * k; const T = pick(['học sinh', 'quyển sách', 'cây', 'm vải']); return Q({ text: `Tính ${frac(n, d)} của ${b} ${T}.`, answer: n * k, wrongs: [b * d / n === Math.floor(b * d / n) ? b * d / n : n * k + 1, k, (d - n) * k], unit: T, hint: '“Phân số của một số” → nhân số đó với phân số.', steps: [`${b} · ${frac(n, d)} = ${b} : ${d} · ${n} = ${k} · ${n} = <b>${n * k}</b> (${T}).`], solVisual: d <= 10 ? { type: 'bar', rows: [{ label: b + '', segs: Array.from({ length: d }, (_, i) => ({ v: k, inner: i < n ? String(k) : '', dashed: i >= n })) }] } : null }); } },
      { level: 3, name: 'Tìm một số biết phân số', fn() { const d = R(2, 9), n = R(1, d - 1), k = R(2, 15); if (gcd(n, d) !== 1) return this.fn(); const a = n * k; return Q({ text: `${frac(n, d)} số sách trên giá là ${a} quyển. Hỏi trên giá có tất cả bao nhiêu quyển sách?`, answer: d * k, wrongs: [a * n, Math.round(a * n / d) || a + 1, d * k + k], unit: 'quyển', hint: 'Biết giá trị phân số của một số → chia cho phân số đó.', steps: [`Số sách: ${a} : ${frac(n, d)} = ${a} · ${frac(d, n)} = <b>${d * k}</b> (quyển).`], solVisual: d <= 10 ? { type: 'bar', rows: [{ label: '?', segs: Array.from({ length: d }, (_, i) => ({ v: k, inner: i < n ? String(k) : '', dashed: i >= n })) }], right: { text: '? quyển', q: true } } : null }); } },
      { level: 3, name: 'Bài toán còn lại', fn() { const d1 = pick([3, 4, 5]), n1 = 1, k = R(2, 6); const total = d1 * 4 * k; const day1 = total * n1 / d1; const rest = total - day1; const day2 = rest / 4 * pick([1, 2, 3]); const left = rest - day2; return Q({ text: `Một cửa hàng có ${total} kg gạo. Ngày đầu bán ${frac(1, d1)} số gạo, ngày thứ hai bán ${fracHtml(day2 / (rest / 4), 4)} số gạo còn lại. Hỏi cửa hàng còn bao nhiêu kg gạo?`, answer: left, unit: 'kg', hint: 'Lưu ý: ngày thứ hai tính theo số gạo CÒN LẠI sau ngày đầu.', steps: [`Ngày đầu bán: ${total} · ${frac(1, d1)} = ${day1} (kg). Còn: ${total} − ${day1} = ${rest} (kg).`, `Ngày hai bán: ${rest} · ${fracHtml(day2 / (rest / 4), 4)} = ${day2} (kg).`, `Còn lại: ${rest} − ${day2} = <b>${left}</b> (kg).`] }); } },
      { level: 3, name: 'Tổng phân số đặc biệt', fn() { const v = R(0, 2), n = R(3, 9); if (v === 1) { const terms = Array.from({ length: n }, (_, i) => frac(2, `${2 * i + 1}·${2 * i + 3}`)); return Q({ text: `Tính nhanh: ${terms.join(' + ')}`, answer: `${2 * n}/${2 * n + 1}`, simplest: true, hint: `Tách ${frac(2, 'k·(k+2)')} = ${frac(1, 'k')} − ${frac(1, 'k+2')}.`, steps: [`= (1 − ${frac(1, 3)}) + (${frac(1, 3)} − ${frac(1, 5)}) + … + (${frac(1, 2 * n - 1)} − ${frac(1, 2 * n + 1)})`, `= 1 − ${frac(1, 2 * n + 1)} = <b>${frac(2 * n, 2 * n + 1)}</b>.`] }); } if (v === 2) { const terms = Array.from({ length: n - 1 }, (_, i) => frac(1, `${i + 2}·${i + 3}`)); const [x, y] = simplify(n - 1, 2 * (n + 1)); return Q({ text: `Tính nhanh: ${terms.join(' + ')}`, answer: `${x}/${y}`, simplest: true, hint: `Tách ${frac(1, 'k·(k+1)')} = ${frac(1, 'k')} − ${frac(1, 'k+1')}.`, steps: [`= (${frac(1, 2)} − ${frac(1, 3)}) + (${frac(1, 3)} − ${frac(1, 4)}) + … + (${frac(1, n)} − ${frac(1, n + 1)})`, `= ${frac(1, 2)} − ${frac(1, n + 1)} = <b>${frac(x, y)}</b>.`] }); } const terms = Array.from({ length: n }, (_, i) => frac(1, `${i + 1}·${i + 2}`)); return Q({ text: `Tính nhanh: ${terms.join(' + ')}`, answer: `${n}/${n + 1}`, simplest: true, hint: `Tách ${frac(1, 'k·(k+1)')} = ${frac(1, 'k')} − ${frac(1, 'k+1')}.`, steps: [`= (1 − ${frac(1, 2)}) + (${frac(1, 2)} − ${frac(1, 3)}) + … + (${frac(1, n)} − ${frac(1, n + 1)})`, `= 1 − ${frac(1, n + 1)} = <b>${frac(n, n + 1)}</b>.`] }); } }
    ]
  });

