      { level: 3, name: 'Giảm giá', fn() { const price = R(10, 50) * 10000, p = pick([10, 15, 20, 25, 30, 40]); const v = price * (100 - p) / 100; return Q({ text: `Một chiếc cặp giá ${fmt(price)} đồng, cửa hàng giảm giá ${p}%. Hỏi giá chiếc cặp sau khi giảm là bao nhiêu đồng?`, answer: v, wrongs: [price * p / 100, price - p * 1000, v + price * 5 / 100], unit: 'đồng', hint: `Giá mới = ${100 - p}% giá cũ.`, steps: [`Số tiền được giảm: ${fmt(price)} · ${p} : 100 = ${fmt(price * p / 100)} (đồng).`, `Giá mới: ${fmt(price)} − ${fmt(price * p / 100)} = <b>${fmt(v)}</b> (đồng).`] }); } },
      { level: 3, name: 'Tăng rồi giảm', fn() { const p = pick([10, 20, 30, 40, 50, 60, 25, 15, 5]); const v = (100 + p) * (100 - p) / 100; return Q({ text: `Giá một món hàng tăng ${p}%, sau đó giảm ${p}%. So với giá ban đầu, giá cuối bằng bao nhiêu phần trăm?`, answer: v, unit: '%', wrongs: [100, 100 - p, 100 + p], hint: 'Giả sử giá ban đầu là 100.', steps: [`Sau khi tăng: 100 + ${p} = ${100 + p}.`, `Sau khi giảm ${p}% của ${100 + p}: ${100 + p} − ${fmt((100 + p) * p / 100)} = ${fmt(v)}.`, `Giá cuối bằng <b>${fmt(v)}%</b> giá ban đầu (giảm so với ban đầu).`] }); } }
