      { title: 'Trung điểm của đoạn thẳng', desc: 'M là trung điểm của AB khi M nằm giữa A, B và MA = MB = AB : 2.', example: 'AB = 8 cm → MA = MB = 4 cm', tip: 'Trung điểm chia đoạn thẳng thành hai phần bằng nhau.', visual: { type: 'shape', kind: 'segment', points: [{ x: 40, n: 'A' }, { x: 150, n: 'M', c: '#e5534b' }, { x: 260, n: 'B' }], lens: [{ a: 40, b: 150, t: '4 cm' }, { a: 150, b: 260, t: '4 cm' }] } },
      { title: 'Đếm đường thẳng, đoạn thẳng', desc: 'Qua n điểm, trong đó không có 3 điểm nào thẳng hàng, vẽ được n(n − 1) : 2 đường thẳng.', formula: 'Số đường thẳng = n · (n − 1) : 2', example: '5 điểm → 5 · 4 : 2 = 10 đường thẳng', tip: 'Mỗi điểm nối với (n − 1) điểm còn lại, mỗi đường được đếm 2 lần.' },
      { title: 'Góc và số đo góc', desc: 'Góc nhọn: < 90°. Góc vuông: = 90°. Góc tù: giữa 90° và 180°. Góc bẹt: = 180°.', example: '∠xOy = 120° là góc tù', tip: 'Dùng thước đo góc, đặt tâm thước trùng đỉnh góc.', visual: { type: 'angle', deg: 60 } }
