      { level: 3, name: 'Phần trăm từ biểu đồ', fn() { const total = pick([40, 50]); const vals = [R(2, 8) * 2, R(2, 8) * 2, R(2, 8) * 2]; const last = total - vals.reduce((a, b) => a + b, 0); if (last <= 0) return this.fn(); const data = ['Bơi', 'Cầu lông', 'Bóng đá', 'Cờ vua'].map((l, i) => ({ label: l, value: i < 3 ? vals[i] : last })); const k = R(0, 3); return Q({ text: `Lớp có ${total} học sinh, mỗi bạn chọn một môn thể thao (xem biểu đồ). Số bạn chọn <b>${data[k].label}</b> chiếm bao nhiêu phần trăm?`, visual: { type: 'barchart', data, unit: 'Số HS', tick: 4 }, answer: data[k].value * 100 / total, wrongs: [data[k].value, data[k].value * 100 / total + 5, 100 - data[k].value * 100 / total], unit: '%', hint: 'Tỉ số % = số bạn : tổng số · 100%.', steps: [`${data[k].value} : ${total} · 100% = <b>${fmt(data[k].value * 100 / total)}%</b>.`] }); } }
